package chihalu.customstacklimit;

import net.fabricmc.api.ClientModInitializer;
import net.fabricmc.fabric.api.client.command.v2.ClientCommandManager;
import net.fabricmc.fabric.api.client.command.v2.ClientCommandRegistrationCallback;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import net.minecraft.client.MinecraftClient;
import net.minecraft.text.Text;

public class CustomStackLimitClient implements ClientModInitializer {
	public static final Logger LOGGER = LoggerFactory.getLogger("customstacklimit");

	@Override
	public void onInitializeClient() {
		LOGGER.info("CustomStackLimit (クライアント専用) Mod が初期化されました！");

		// クライアント側コマンドを登録
		ClientCommandRegistrationCallback.EVENT.register((dispatcher, registryAccess) -> {
			dispatcher.register(ClientCommandManager.literal("stack")
				.then(ClientCommandManager.argument("count", IntegerArgumentType.integer(1, 99))
					.executes(context -> {
						MinecraftClient client = MinecraftClient.getInstance();
						if (client.player != null) {
							int stackLimit = IntegerArgumentType.getInteger(context, "count");

							// プレイヤーのスタック数を設定
							StackLimitConfig.setPlayerStackLimit(client.player.getUuid(), stackLimit);

							// 成功メッセージを表示
							client.player.sendMessage(
								Text.literal("§aアイテムのスタック数を " + stackLimit + " 個に設定しました！"),
								false
							);

							// インベントリを更新
							if (client.player.currentScreenHandler != null) {
								client.player.currentScreenHandler.syncState();
							}

							LOGGER.info("スタック数を{}に設定しました (プレイヤー: {})", stackLimit, client.player.getName().getString());
						}
						return 1;
					}))
				.executes(context -> {
					MinecraftClient client = MinecraftClient.getInstance();
					if (client.player != null) {
						int currentLimit = StackLimitConfig.getPlayerStackLimit(client.player.getUuid());
						client.player.sendMessage(
							Text.literal("§e現在のスタック数: " + currentLimit + " 個"),
							false
						);
					}
					return 1;
				}));
		});

		LOGGER.info("CustomStackLimit: /stack コマンドが登録されました（クライアント専用）");
	}
}
